// === Tab: mySketch ===
let font;
const POINT_SPAN = 5;
let particles = [];
let spd = 5;
let col = 0;

function setup() {
	createCanvas(1112, 834);
	colorMode(HSB, 255);
	textSize(height*0.26);

	opentype.load("f.otf",function(err,f){
		if(err)print("PROGRAM");
		else
		{
			font = f;
			textFont(f);
			drawStr('PROGRAM');
			loop();
		} 
	});
}


function draw(){
	background('#ECECEC44');
	for(let i = particles.length-1; i >= 0; i--)
	{
		particles[i].update();
		if(particles[i].x < 0)particles.splice(i,1);
		if(particles[i].x < 35) noLoop();
	}
}

//////////

function keyPressed() {
	if(keyCode >= 48 && keyCode <= 90 && font != null)
	{
		drawStr(key);
	}
}

//////////

function drawStr(st)
{
	let p = getGPointsFromStr(st);
	particles = particles.concat(getParticlesFromPoints(p));
}


function getGPointsFromStr(str)
{
	let w = textWidth(str);	
	let tSize = textSize();
	let fontpath = font.getPath(str, width-w, height/2+tSize*0.35, tSize);
	let gpath = new g.Path(fontpath.commands);
	gpath = g.resampleByLength(gpath,POINT_SPAN).commands;
	return gpath;
}


function getParticlesFromPoints(pathData){
	var p = [];
	let lifeTimeScale = random(1,5);
	for(let i = 0; i < pathData.length; i++)
	{
		if(pathData[i].type == "Z")continue;
		let x = pathData[i].x;
		let y = pathData[i].y;
		col = i/pathData.length * 255;
		p.push(new Particle(x, y, col));
	}
	return p;
}

/////

class Particle
{
	constructor(x, y, col)
	{
		this.x = width + x + random(-.1,.1);
		this.y= y + random(-.1,.1);
		this.angle = 0;
		this.speed = spd;
		this.col = col;
	}

	update()
	{
		this.x += cos(this.angle) * this.speed;
		this.y += sin(this.angle) * this.speed;
		let noiseScale = 0.008;
		let noiseVal = noise(this.x*noiseScale,this.y *noiseScale);
		this.angle = map(noiseVal,0,1,PI-PI/20,PI+PI/20);
		noStroke();
		fill(this.col, 255, 220);
		circle(this.x,this.y,POINT_SPAN/2);
	}

}

